INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0114',114,'There is a job here','اینجا یک شغل هست','با job درباره یک فرصت شغلی ساده حرف بزن.','EN-A1-OUTCOME-0114',420,'3bd4d4427f733ea94b3a7ff09fb8d63a7fd2107efe4336eebac510935edab5c1','validated','{"outcomeFa":"job را به معنی «شغل» در دو جمله کوتاه به کار ببری.","scenarioFa":"آیریس و نینا روی تابلوی اعلانات مرکز محله یک آگهی استخدام کافه می‌بینند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0113"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0114-JOB","form":"There is a job here","meaningFa":"گفتن اینکه یک فرصت شغلی وجود دارد"}],"supportLanguage":[{"form":"What is this notice?","meaningFa":"این اعلان چیست؟"},{"form":"At the cafe?","meaningFa":"در کافه؟"}],"assessmentBoundary":"Only the bounded A1 employment sense of job is assessed.","transferPlan":{"mode":"same_lesson","intent":"Reuse job in a second controlled location reference."},"story":{"arcKey":"EN-A1-COMMUNITY","sceneKey":"EN-A1-FACTORY-SCENE-0114","learnerRoleKey":"nina","participants":["iris","nina"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0109"],"continuesLessonKey":"EN-A1-L-0109","settingFa":"مرکز محله، کنار تابلوی اعلانات","storyBeatFa":"آیریس درباره اعلان می‌پرسد و نینا با job توضیح می‌دهد که یک فرصت شغلی در کافه وجود دارد."},"reviewLinks":[{"lessonKey":"EN-A1-L-0109","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning community arc is spaced by 5 Lessons and the played role changes from Iris to Nina."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0114","specHash":"5e682ce046ce27a152b8d5060aaf3f550132757d2dbf584b5c40175fccdd65ca","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"is a job here","rationale":"Exact deterministic target-collocation window from There is a job here for the bounded employment sense."},{"query":"is a job at the","rationale":"Exact deterministic validator window from the natural utterance There is a job at the cafe, preserving the employment sense."}],"noNewGrammarReason":"Lexical-focus Lesson using familiar there-is support language; no new grammar is claimed."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
